   677      hour = ((p[0] - '0') * 10) + (p[1] - '0');
   678      if (end - p == 5 && p[2] == ':') {
   679          min = ((p[3] - '0') * 10) + (p[4] - '0');
   680      }
   681      else {
   682          min = ((p[2] - '0') * 10) + (p[3] - '0');
   683      }
   684
