   697  int flb_parser_time_lookup(const char *time_str, size_t tsize,
   698                             time_t now,
   699                             struct flb_parser *parser,
   700                             struct tm *tm, double *ns)
   701  {
   702      int ret;
   703      int slen;
   704      time_t time_now;
   705      double tmfrac = 0;
   706      char *p = NULL;
   707      char *fmt;
   708      int time_len = tsize;
   709      const char *time_ptr = time_str;
   710      char tmp[64];
   711      char fs_tmp[32];
   712      struct tm tmy;
   713
   714      *ns = 0;
   715
   716      if (tsize > sizeof(tmp) - 1) {
   717          flb_error("[parser] time string length is too long");
   718          return -1;
   719      }
   720
   721      /*
   722       * Some records coming from old Syslog messages do not contain the
   723       * year, so it's required to ingest this information in the value
   724       * to be parsed.
   725       */
   726      if (parser->time_with_year == FLB_FALSE) {
   727          /* Given time string is too long */
   728          if (time_len + 6 >= sizeof(tmp)) {
   729              return -1;
   730          }
   731
   732          /*
   733           * This is not the most elegant way but for now it let
   734           * get the work done.
   735           */
   736          if (now <= 0) {
   737              time_now = time(NULL);
   738          }
   739          else {
   740              time_now = now;
   741          }
   742
   743          gmtime_r(&time_now, &tmy);
   744
   745          /* Make the timestamp default to today */
   746          tm->tm_mon = tmy.tm_mon;
   747          tm->tm_mday = tmy.tm_mday;
   748
   749          uint64_t t = tmy.tm_year + 1900;
   750
   751          fmt = tmp;
   752          u64_to_str(t, fmt);
   753          fmt += 4;
   754          *fmt++ = ' ';
   755
   756          memcpy(fmt, time_ptr, time_len);
   757          fmt += time_len;
   758          *fmt++ = '\0';
   759
   760          time_ptr = tmp;
   761          time_len = strlen(tmp);
   762          p = flb_strptime(time_ptr, parser->time_fmt_year, tm);
   763      }
   764      else {
   765          p = flb_strptime(time_ptr, parser->time_fmt, tm);
   766      }
   767
   768      if (p != NULL) {
   769          /* Check if we have fractional seconds */
   770          if (parser->time_frac_secs && (*p == '.' || *p == ',')) {
   771              /*
   772               * Further parser routines needs a null byte, for fractional seconds
   773               * we make a safe copy of the content.
   774               */
   775              slen = time_len - (p - time_ptr);
   776              if (slen > 31) {
   777                  slen = 31;
   778              }
   779              memcpy(fs_tmp, p, slen);
   780              fs_tmp[slen] = '\0';
   781
   782              /* Parse fractional seconds */
   783              ret = flb_parser_frac(fs_tmp, slen, &tmfrac, &time_ptr);
   784              if (ret == -1) {
   785                  flb_warn("[parser] Error parsing time string");
   786                  return -1;
   787              }
   788              *ns = tmfrac;
   789
   790              p = flb_strptime(time_ptr, parser->time_frac_secs, tm);
   791
   792              if (p == NULL) {
   793                  return -1;
   794              }
   795          }
   796
   797  #ifdef FLB_HAVE_GMTOFF
   798          if (parser->time_with_tz == FLB_FALSE) {
   799              tm->tm_gmtoff = parser->time_offset;
   800          }
   801  #endif
   802
   803          return 0;
   804      }
   805
   806      return -1;
   807  }
