   809  int flb_parser_frac(const char *str, int len, double *frac, const char **end)
   810  {
   811      int ret = 0;
   812      char *p;
   813      double d;
   814      const char *pstr;
   815      char *tmp = NULL;
   816
   817      /* Fractional seconds */
   818      /* Normalize the fractional seperator to be '.' since that's what strtod()
   819       * expects in standard C locale */
   820      if (*str == ',') {
   821          tmp = flb_strdup(str);
   822          tmp[0] = '.';
   823          pstr = tmp;
   824      }
   825      else {
   826          pstr = str;
   827      }
   828
   829      d = strtod(pstr, &p);
   830      if ((d == 0 && p == pstr) || !p) {
   831          ret = -1;
   832          goto free_and_return;
   833      }
   834      *frac = d;
   835      *end = str + (p - pstr);
   836
   837  free_and_return:
   838      if (tmp != NULL) {
   839          flb_free(tmp);
   840      }
